  void AddAsyncButton(Control parent,string title,Func<Task> action){var b=new Button {Text=title,AutoSize=true};b.Click+=async(s,e)=>{if(busy)return;busy=true;b.Enabled=false;Submit.Enabled=false;try{await action();}catch(Exception ex){Error(ex);}finally{busy=false;if(!IsDisposed){b.Enabled=true;Submit.Enabled=api!=null&&api.Connected&&Editable();}}};parent.Controls.Add(b);}
  void AddButton(Control parent,string title,Action action){var b=new Button {Text=title,AutoSize=true};b.Click+=(s,e)=>{try{action();}catch(Exception ex){Error(ex);}};parent.Controls.Add(b);}
  void Say(string message){log.AppendText(DateTime.Now.ToString("HH:mm:ss")+" "+message+Environment.NewLine);if(log.TextLength>24000)log.Text=log.Text.Substring(log.TextLength-16000);}
  void Error(Exception ex){Say(ex is ApiException?ex.Message:"操作失败："+ex.Message);var ae=ex as ApiException;if(ae!=null&&(ae.Status==401||ae.Status==403)){ClearSession();Say("权限失效，已清理管理数据，请重新登录。");}}
  void ClearSession(bool dispose=true){generation++;if(api!=null&&dispose)api.Dispose();api=null;current=admin=selected=baseline=baselineView=lastEnvelope=null;observer=new Observer();rows.Clear();Items.Items.Clear();Detail.Clear();log.Clear();fields.Controls.Clear();editors.Clear();includes.Clear();Operation.Items.Clear();receiptId.Clear();Password.Clear();uncertain=false;lastDigest=viewDigest="";segment=-1;nextAdmin=DateTime.MinValue;adminFailures=0;adminError="";Submit.Enabled=false;Connect.Text="连接";status.Text="未连接";}
  async Task Disconnect(){var old=api;ClearSession(false);if(old!=null)try{await old.Logout();}catch{} }
  public async Task Login(){Connect.Enabled=false;int g=++generation;ApiClient candidate=null;try{candidate=new ApiClient(Address.Text);await candidate.Login(Account.Text,Password.Text);if(g!=generation){candidate.Dispose();return;}api=candidate;Password.Clear();Connect.Text="断开";Operation.Items.AddRange(Ops.Where(x=>J.D(J.Get(api.Contracts,"operations")).ContainsKey(x)).Cast<object>().ToArray());Operation.SelectedIndex=0;adminTime=DateTime.MinValue;Say("已登录。等待完整房间快照；观察仅代表收到的样本。");}catch(Exception ex){if(candidate!=null)candidate.Dispose();if(g==generation){ClearSession();Error(ex);}}finally{Connect.Enabled=true;}}
  public async Task Tick(){if(ticking||api==null)return;ticking=true;var client=api;var observation=observer;int g=generation;try{if(client.LastError=="AUTH_RESET"||client.LastError=="需要 KP 权限"){ClearSession();return;}var v=client.View;if(v==null||!client.Connected){Submit.Enabled=false;status.Text="断线/等待快照："+client.LastError;return;}bool newSegment=segment!=client.Segment;if(newSegment){segment=client.Segment;observer.Reset();admin=null;adminTime=DateTime.MinValue;nextAdmin=DateTime.MinValue;adminFailures=0;adminError="";selected=baseline=baselineView=lastEnvelope=null;fields.Controls.Clear();Detail.Clear();lastDigest="";Say("新观察段：此前断线期间变化无法补齐，已重建基线。");}
    current=v;if(newSegment)BuildFields();string digest=J.Canon(v);if(digest!=viewDigest){viewDigest=digest;viewTime=DateTime.Now;await Task.Run(()=>observation.Sample("view",Observer.Collections(v)));if(g!=generation)return;}
    if(DateTime.Now>=nextAdmin&&(DateTime.Now-adminTime).TotalMilliseconds>=Options.AdminPollMilliseconds){var a=await client.Admin();if(g!=generation)return;await Task.Run(()=>observation.Sample("admin",Observer.Collections(a)));if(g!=generation)return;admin=a;adminTime=DateTime.Now;nextAdmin=adminTime.AddMilliseconds(Options.AdminPollMilliseconds);adminFailures=0;adminError="";}
    status.Text="已连接 · WS "+viewTime.ToString("HH:mm:ss")+" / 管理 "+adminTime.ToString("HH:mm:ss")+(adminError==""?"":" · 管理数据过期，退避重试");Submit.Enabled=!busy&&client.Connected&&Editable();Render();
   }catch(Exception ex){if(g==generation){adminError=ex.Message;adminFailures=Math.Min(adminFailures+1,4);nextAdmin=DateTime.Now.AddSeconds(Math.Min(30,Math.Pow(2,adminFailures)));Submit.Enabled=false;Error(ex);}}finally{ticking=false;}}
  object Data(string name){if(name=="概览")return J.Obj("room",current,"管理运行信息",J.Get(admin,"runtime"),"存储信息",J.Get(admin,"store"));if(name=="观察到的变化")return observer.Records.Select(r=>{var copy=J.D(J.Clone(r));copy["关注命中"]=settings.Watches.Any(w=>MatchesContext(w)&&J.B(w,"enabled")&&WatchMatches(w,r));return (object)copy;}).Where(r=>!watchedOnly.Checked||J.B(r,"关注命中")).ToArray();if(name=="关注")return settings.Watches.Where(MatchesContext).ToArray();if(name=="命令记录")return settings.Commands.Where(MatchesContext).ToArray();if(name=="宿主最近审计")return J.Get(admin,"audit");return J.Get(admin,name,J.Get(current,name));}
  static bool WatchMatches(object w,object r){string prefix="/"+Observer.Escape(J.S(w,"collection"))+"/"+Observer.Escape(J.S(w,"objectId"))+J.S(w,"path");string path=J.S(r,"path");return path==prefix||path.StartsWith(prefix+"/")||prefix.StartsWith(path+"/");}
  bool MatchesContext(object entry){return api!=null&&current!=null&&J.S(entry,"endpoint")==api.Origin.ToString()&&J.S(entry,"accountId")==J.S(current,"accountId")&&J.S(entry,"roomId")==J.S(current,"roomId")&&J.S(entry,"runId")==J.S(current,"runId");}
  List<Row> ToRows(object data){var d=data as Dictionary<string,object>;if(d!=null)return d.Select(x=>new Row {Key=x.Key,Value=x.Value}).ToList();int n=0;return J.List(data).Select(x=>new Row {Key=x is string?(string)x:J.S(x,"id",J.S(x,"accountId",J.S(x,"configurationId",J.S(x,"assetId",J.S(x,"revision",(++n).ToString()))))),Value=x}).ToList();}
  void Render(){if(api==null)return;var data=Data(Collection.Text);string digest=J.Canon(data)+search.Text+page+watchedOnly.Checked;if(digest==lastDigest)return;lastDigest=digest;var all=ToRows(data).Where(x=>(x.Key+J.Text(x.Value)).IndexOf(search.Text,StringComparison.OrdinalIgnoreCase)>=0).OrderBy(x=>x.Key,StringComparer.Ordinal).ToList();page=Math.Min(page,Math.Max(0,(all.Count-1)/500));rows=all.Skip(page*500).Take(500).ToList();listStatus.Text="共 "+all.Count+" 项 · 第 "+(page+1)+" 页（本地）"+(Collection.Text=="观察到的变化"?" · 已淘汰 "+observer.Dropped:"");string key=(Items.SelectedItem as Row)==null?null:((Row)Items.SelectedItem).Key;rendering=true;Items.BeginUpdate();try{Items.Items.Clear();Items.Items.AddRange(rows.Cast<object>().ToArray());if(key!=null){int index=rows.FindIndex(x=>x.Key==key);if(index>=0){Items.SelectedIndex=index;selected=rows[index].Value;Detail.Text=J.Pretty(selected);}}}finally{Items.EndUpdate();rendering=false;}}
  void Rebase(){if(baselineCollection==Collection.Text){var row=ToRows(Data(Collection.Text)).FirstOrDefault(x=>x.Key==baselineKey);if(row!=null)selected=row.Value;}BuildFields();}
  void Compare(){var row=ToRows(Data(baselineCollection)).FirstOrDefault(x=>x.Key==baselineKey);Detail.Text=J.Pretty(J.Obj("开始编辑时",baseline,"当前样本",row==null?null:row.Value,"表单草稿",Arguments(),"说明","比较不会提交或更新编辑基线"));}
  bool Editable(){return Collection.Text!="观察到的变化"&&Collection.Text!="关注"&&Collection.Text!="宿主最近审计"&&Collection.Text!="命令记录";}
  public void BuildFields(){fields.Controls.Clear();editors.Clear();includes.Clear();Operation.Enabled=Editable();Submit.Enabled=api!=null&&api.Connected&&!busy&&Editable();if(!Editable()){fields.Controls.Add(new Label {Text="此类别只读。请切换到对应的房间对象类别后编辑。",AutoSize=true});return;}if(api==null||Operation.Text=="")return;baseline=selected==null?null:J.Clone(selected);baselineView=current==null?null:J.Clone(current);baselineCollection=Collection.Text;baselineKey=(Items.SelectedItem as Row)==null?baselineKey:((Row)Items.SelectedItem).Key;var schema=J.Get(J.Get(api.Contracts,"operations"),Operation.Text);var required=J.List(J.Get(schema,"required")).Select(Convert.ToString).ToArray();fields.Controls.Add(new Label {Text=Operation.Text.StartsWith("entity.")&&Operation.Text!="entity.create"?"实体使用开始编辑时的版本；冲突后草稿保留。":"无原子版本保护：提交前刷新只能发现部分外部修改。",AutoSize=true});
   foreach(var pair in J.D(J.Get(schema,"properties"))){var row=new FlowLayoutPanel {AutoSize=true,Width=650};bool req=required.Contains(pair.Key);var check=new CheckBox {Text=FieldLabel(pair.Key)+(req?" *":""),Checked=req,Enabled=!req,Width=155};includes[pair.Key]=check;row.Controls.Add(check);object value=J.Get(selected,pair.Key);if(value==null&&(pair.Key=="id"||pair.Key=="configurationId"||pair.Key=="assetId"||pair.Key=="flowId"||pair.Key=="waitId"))value=J.Get(selected,"id",J.Get(selected,"instanceId",J.Get(selected,"relationId",baselineKey)));Control control;var choices=J.List(J.Get(pair.Value,"enum"));if(choices.Count>0){var c=new ComboBox {DropDownStyle=ComboBoxStyle.DropDownList,Width=370};c.Items.AddRange(choices.ToArray());c.SelectedIndex=value==null?0:Math.Max(0,c.Items.IndexOf(value));control=c;}else if(J.S(pair.Value,"type")=="boolean"){control=new CheckBox {Checked=value is bool&&(bool)value};}else {string type=J.S(pair.Value,"type");bool json=type=="object"||type=="array"||type=="number"||type=="integer"||pair.Key=="value";control=new TextBox {Width=370,Text=value==null?(type=="object"?"{}":type=="array"?"[]":""):(json?J.Text(value):Convert.ToString(value)),Multiline=json,Height=json?55:26,ScrollBars=json?ScrollBars.Vertical:ScrollBars.None};}control.Name="field_"+pair.Key;control.Tag=pair.Value;editors[pair.Key]=control;row.Controls.Add(control);fields.Controls.Add(row);}
  }
  static string FieldLabel(string key){var labels=new Dictionary<string,string>{{"id","对象 ID"},{"name","名称"},{"numbers","数值表 JSON"},{"tags","标签 JSON 数组"},{"owner","所有者 / null"},{"visibility","可见性"},{"rules","规则绑定 JSON"},{"configurationId","配置 ID"},{"revision","修订"},{"typeRef","对象类型"},{"defaults","默认数值 JSON"},{"behaviors","默认行为 JSON"},{"sourceId","来源 ID"},{"targetId","目标 ID"},{"relationType","关系类型"},{"metadata","元数据 JSON"},{"ownerKind","进度归属类型"},{"ownerId","进度归属 ID"},{"eventKey","事件键"},{"value","进度值 JSON"},{"status","状态"},{"accountId","账号 ID"},{"active","启用"},{"role","角色"},{"sources","Lua 文件组 JSON"},{"data","数据文件组 JSON"},{"waitId","等待 ID"},{"answer","回答：是"},{"flowId","流程 ID"},{"entityId","实体 ID"},{"assetId","素材 ID"}};return labels.ContainsKey(key)?labels[key]:key;}
  public object Arguments(){var args=J.Obj();foreach(var pair in editors){if(!includes[pair.Key].Checked)continue;var c=pair.Value;object value;var check=c as CheckBox;var combo=c as ComboBox;string type=J.S(c.Tag,"type");if(check!=null)value=check.Checked;else if(combo!=null)value=combo.SelectedItem;else if(type=="object"||type=="array"||type=="number"||type=="integer"||pair.Key=="value")value=J.Parse(c.Text);else value=c.Text=="null"&&J.List(J.Get(c.Tag,"type")).Contains("null")?null:(object)c.Text;var schema=J.D(c.Tag);if(value is string&&((string)value).Length<J.I(schema,"minLength"))throw new ApiException(pair.Key+" 不能为空");if(value is string&&((string)value).Length>J.I(schema,"maxLength",Int32.MaxValue))throw new ApiException(pair.Key+" 过长");if(type=="object"&&!(value is Dictionary<string,object>))throw new ApiException(pair.Key+" 必须是对象");if(type=="array"&&!(value is object[]))throw new ApiException(pair.Key+" 必须是数组");args[pair.Key]=value;}RoomManager.Validate.Check(J.Get(J.Get(api.Contracts,"operations"),Operation.Text),args);return args;}
  public void SetField(string key,string value){if(!editors.ContainsKey(key))throw new Exception("未知字段 "+key);includes[key].Checked=true;var c=editors[key];if(c is ComboBox)((ComboBox)c).SelectedItem=value;else if(c is CheckBox)((CheckBox)c).Checked=Boolean.Parse(value);else c.Text=value;}
  async Task Execute(object envelope){var client=api;int g=generation;lastEnvelope=envelope;settings.Remember(client.Origin.ToString(),current,envelope);receiptId.Text=J.S(J.Get(envelope,"payload"),"commandId");uncertain=true;try{var result=await client.Send(envelope);if(g!=generation)return;uncertain=J.S(result,"status")=="pending";Say(J.Text(result));adminTime=DateTime.MinValue;nextAdmin=DateTime.MinValue;}catch(Exception ex){if(g!=generation)return;var failure=ex as ApiException;if(failure!=null&&failure.Status>0){uncertain=false;Say("宿主已拒绝请求，草稿保留。");}else Say("结果未知；请用此 commandId 查询回执，勿换 ID 重试。");Error(ex);}}
  public async Task Send(){if(busy||api==null||!Editable())return;if(uncertain){Say("上一命令结果仍未知。请先查询回执或原封套重发，不能换新 commandId 重做。");return;}busy=true;Submit.Enabled=false;int g=generation;try{var args=Arguments();string op=Operation.Text;var tokens=J.Obj();if(op.StartsWith("entity.")&&op!="entity.create"||op=="asset.attach"){string id=J.S(args,op=="asset.attach"?"entityId":"id");if(baselineView==null)throw new ApiException("请先重建编辑基线");var entity=J.Get(J.Get(baselineView,"entities"),id);if(entity==null){entity=J.List(J.Get(baselineView,"entities")).FirstOrDefault(x=>J.S(x,"id")==id);}if(entity==null)throw new ApiException("请先选中该实体并重建编辑基线");tokens[id]=J.Get(entity,"viewToken");}else if(baseline!=null&&baselineCollection!="概览"&&baselineCollection!="artifacts"){var fresh=await api.Admin();if(g!=generation)return;var fv=await api.Request("view");if(g!=generation)return;var row=ToRows(J.Get(fresh,baselineCollection,J.Get(fv,baselineCollection))).FirstOrDefault(x=>x.Key==baselineKey);if(row==null||J.Canon(row.Value)!=J.Canon(baseline))throw new ApiException("选中数据已变化；草稿保留，请与最新数据比较后重建编辑基线。");}
    if(op=="rule.activate"||op=="entity.archive"||op=="member.update"||op=="room.status"||op.EndsWith("remove")||op=="flow.retry"){if(MessageBox.Show(this,op+"\r\n"+J.Pretty(args)+(op=="flow.retry"?"\r\n这是新尝试，可能重新掷骰。":""),"确认提交",MessageBoxButtons.OKCancel)!=DialogResult.OK)return;}await Execute(api.Envelope(op,args,tokens));
   }catch(Exception ex){if(g==generation)Error(ex);}finally{busy=false;Submit.Enabled=api!=null&&api.Connected&&Editable();}}
  async Task Resend(){try{if(lastEnvelope==null)throw new ApiException("无内存中的原封套；重启后仅可查询回执。");if(MessageBox.Show(this,"使用相同 commandId 和相同参数重发？","原封套重发",MessageBoxButtons.OKCancel)==DialogResult.OK)await Execute(lastEnvelope);}catch(Exception ex){Error(ex);}}
  async Task Receipt(){var c=api;int g=generation;try{if(c==null)return;var r=await c.Receipt(receiptId.Text.Trim());if(g==generation){if(receiptId.Text==J.S(J.Get(lastEnvelope,"payload"),"commandId"))uncertain=J.S(r,"status")!="committed"&&J.S(r,"status")!="rejected";Say(J.Text(r));}}catch(Exception ex){if(g==generation)Error(ex);}}
  void ImportRules(){if(api==null)return;using(var dialog=new OpenFileDialog {Multiselect=true,Filter="规则文件|*.lua;*.json"}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;var sources=J.Obj();var data=J.Obj();foreach(var file in dialog.FileNames){var target=Path.GetExtension(file).ToLowerInvariant()==".lua"?sources:data;string name=Path.GetFileName(file);if(target.ContainsKey(name))throw new ApiException("同名文件："+name);target[name]=target==sources?(object)File.ReadAllText(file):J.Parse(File.ReadAllText(file));}if(sources.Count==0)throw new ApiException("完整规则组必须含 Lua 文件");Operation.SelectedItem="rule.stage";SetField("sources",J.Text(sources));SetField("data",J.Text(data));Say("已导入草稿。暂存不激活；请提交后查看修订，再显式激活。");}}
  async Task ReadArtifact(){var c=api;int g=generation;try{if(c==null||selected==null)return;string id=selected is string?(string)selected:J.S(selected,"revision",baselineKey);var r=await c.Request("admin/artifacts/"+Uri.EscapeDataString(id));if(g==generation)Detail.Text=J.Pretty(r);}catch(Exception ex){if(g==generation)Error(ex);}}
  async Task Upload(){var c=api;int g=generation;try{if(c==null||!c.Connected)throw new ApiException("请先连接宿主");using(var d=new OpenFileDialog()){if(d.ShowDialog(this)!=DialogResult.OK)return;if(new FileInfo(d.FileName).Length>10*1024*1024)throw new ApiException("素材最大 10 MiB");var visibility=MessageBox.Show(this,"设为所有房间成员可见？选择否则仅 KP 可见。","素材可见性",MessageBoxButtons.YesNoCancel);if(visibility==DialogResult.Cancel)return;var r=await c.Request("assets","POST",null,File.ReadAllBytes(d.FileName),Path.GetFileName(d.FileName),visibility==DialogResult.Yes?"public":"kp");if(g==generation){Say(J.Text(r));adminTime=DateTime.MinValue;}}}catch(Exception ex){if(g==generation){Say("上传失败时可能结果未知，不会自动重复上传。");Error(ex);}}}
  async Task Download(){var c=api;int g=generation;try{if(c==null||selected==null)return;string id=J.S(selected,"id",J.S(selected,"assetId",baselineKey));var data=await c.Download(id);if(g!=generation)return;using(var d=new SaveFileDialog {FileName=Path.GetFileName(Uri.UnescapeDataString(J.S(selected,"name","asset.bin")))}){if(d.ShowDialog(this)==DialogResult.OK){File.WriteAllBytes(d.FileName,data);Say("已下载素材。");}}}catch(Exception ex){if(g==generation)Error(ex);}}
  async Task Backup(){var c=api;int g=generation;try{if(c==null||!c.Connected)throw new ApiException("请先连接宿主");var r=await c.Request("backup","POST",J.Obj());if(g==generation)Say("备份已由宿主创建（不含身份库）："+J.Text(r));}catch(Exception ex){if(g==generation){Say("备份结果可能未知；不自动重试。首版不支持备份列表/下载/恢复/删除。");Error(ex);}}}
  void AddWatch(){if(api==null||current==null||selected==null||!Editable())return;if(settings.Watches.Count>=Options.WatchLimit)throw new ApiException("关注上限 100 项");string path=watchPath.Text.Trim();if(path!=""&&!path.StartsWith("/"))throw new ApiException("字段路径采用 /numbers/hp 格式，留空关注对象");settings.Watches.Add(J.Obj("endpoint",api.Origin.ToString(),"accountId",J.Get(current,"accountId"),"roomId",J.Get(current,"roomId"),"runId",J.Get(current,"runId"),"collection",Collection.Text,"objectId",baselineKey,"path",path,"enabled",true));settings.Save();Say("已保存关注定义，不保存房间数值。");}
  void ToggleWatch(){if(Collection.Text!="关注"||selected==null)return;J.D(selected)["enabled"]=!J.B(selected,"enabled");settings.Save();lastDigest="";Render();}
  void DeleteWatch(){if(Collection.Text!="关注"||selected==null)return;settings.Watches.Remove(selected);settings.Save();lastDigest="";Render();}
 }
